    private void discover(){int[] types={Sensor.TYPE_MAGNETIC_FIELD,Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_LIGHT,Sensor.TYPE_PRESSURE};String[] names={"Magnetometer","Accelerometer","Gyroscope","Ambient light","Barometer"};StringBuilder summary=new StringBuilder();for(int i=0;i<types.length;i++){Sensor s=sensors.getDefaultSensor(types[i]);if(s!=null)available.add(s);summary.append(s==null?"○ ":"● ").append(names[i]).append(s==null?" unavailable":" ready").append("   ");}inventoryLabel.setText(summary.toString());refreshReadings();}
    private void toggle(){if(!recording){begin();}else if(paused){paused=false;for(Sensor s:available)sensors.registerListener(this,s,SensorManager.SENSOR_DELAY_NORMAL);statusLabel.setText("Recording · hold steady for the 10-second sensor reference");startButton.setText("PAUSE SESSION");}else{paused=true;sensors.unregisterListener(this);statusLabel.setText("Paused · tap resume to continue");startButton.setText("RESUME SESSION");return;}if(!recording)return;}
    private void begin(){recording=true;paused=false;started=SystemClock.elapsedRealtime();sampleCount=0;sessionId=new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());fieldBaselineSum=fieldBaselineSq=fieldBaselineMean=fieldBaselineSd=0;fieldBaselineN=fieldDeviationStreak=0;fieldBaselineReady=false;activityWarning.setVisibility(View.GONE);lastActivityAlert=0;rows.clear();mediaUris.clear();audioFiles.clear();rows.add("elapsed_realtime_ns,wall_time,sensor,x,y,z,accuracy,event,note");logEvent("SESSION_START","case="+caseName+"; site="+site+"; team="+team);statusLabel.setText("Recording · keep app in foreground");startButton.setText("PAUSE SESSION");stopButton.setVisibility(View.VISIBLE);startButton.setBackgroundTintList(android.content.res.ColorStateList.valueOf(AMBER));for(Sensor s:available)sensors.registerListener(this,s,SensorManager.SENSOR_DELAY_NORMAL);handler.post(clock);}
    private void endSession(){if(recorder!=null){try{recorder.stop();if(activeAudio!=null){audioFiles.add(activeAudio);logEvent("AUDIO_CAPTURE",activeAudio.getName());}}catch(RuntimeException e){if(activeAudio!=null)activeAudio.delete();}recorder.reset();recorder.release();recorder=null;}recording=false;paused=false;sensors.unregisterListener(this);handler.removeCallbacks(clock);startButton.setText("START NEW SESSION");stopButton.setVisibility(View.GONE);startButton.setBackgroundTintList(android.content.res.ColorStateList.valueOf(MINT));saveSession();statusLabel.setText("Session saved on this device · "+sampleCount+" samples");}
    private void saveSession(){if(sessionId.isEmpty())return;try{File dir=new File(getFilesDir(),"sessions");if(!dir.exists())dir.mkdirs();File f=new File(dir,"session-"+sessionId+".csv");try(Writer w=new OutputStreamWriter(new FileOutputStream(f),StandardCharsets.UTF_8)){for(String row:rows)w.write(row+"\n");}StringJoiner media=new StringJoiner("|");for(Uri u:mediaUris)media.add(u.toString());StringJoiner audio=new StringJoiner("|");for(File a:audioFiles)audio.add(a.getAbsolutePath());getSharedPreferences("sessions",0).edit().putString("media_"+sessionId,media.toString()).putString("audio_"+sessionId,audio.toString()).putString("case_"+sessionId,caseName).putString("site_"+sessionId,site).putString("team_"+sessionId,team).apply();}catch(IOException e){statusLabel.setText("Could not save session: "+e.getMessage());}}
    @Override public void onSensorChanged(SensorEvent e){float[] v=e.values;if(calibrationActive&&e.sensor.getType()==Sensor.TYPE_MAGNETIC_FIELD){calX+=v[0];calY+=v[1];calZ+=v[2];calibrationSamples++;magnetAccuracy=e.accuracy;return;}if(!recording||paused)return;int type=e.sensor.getType();if(type==Sensor.TYPE_MAGNETIC_FIELD){mx=v[0];my=v[1];mz=v[2];evaluateMagneticChange(v[0],v[1],v[2]);}else if(type==Sensor.TYPE_ACCELEROMETER){ax=v[0];ay=v[1];az=v[2];}else if(type==Sensor.TYPE_GYROSCOPE){gx=v[0];gy=v[1];gz=v[2];}else if(type==Sensor.TYPE_LIGHT)lux=v[0];else if(type==Sensor.TYPE_PRESSURE)pressure=v[0];String wall=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ",Locale.US).format(new Date());rows.add(e.timestamp+","+wall+","+e.sensor.getName().replace(',',' ')+","+v[0]+","+(v.length>1?v[1]:"")+","+(v.length>2?v[2]:"")+","+e.accuracy+",,");sampleCount++;}
    @Override public void onAccuracyChanged(Sensor s,int accuracy){}
    private void evaluateMagneticChange(float x,float y,float z){long elapsed=SystemClock.elapsedRealtime()-started;double magnitude=Math.sqrt(x*x+y*y+z*z);if(!fieldBaselineReady){if(elapsed<=10000){fieldBaselineSum+=magnitude;fieldBaselineSq+=magnitude*magnitude;fieldBaselineN++;}else if(fieldBaselineN>=10){fieldBaselineMean=fieldBaselineSum/fieldBaselineN;fieldBaselineSd=Math.sqrt(Math.max(0,fieldBaselineSq/fieldBaselineN-fieldBaselineMean*fieldBaselineMean));fieldBaselineReady=true;statusLabel.setText("Sensor reference ready · monitoring environmental changes");logEvent("MAGNETIC_BASELINE_READY", String.format(Locale.US,"mean=%.2f µT, SD=%.2f µT, n=%d; ten-second in-session reference",fieldBaselineMean,fieldBaselineSd,fieldBaselineN));}else return;}if(fieldBaselineReady){double threshold=Math.max(12.0,5.0*fieldBaselineSd);if(Math.abs(magnitude-fieldBaselineMean)>=threshold)fieldDeviationStreak++;else fieldDeviationStreak=0;if(fieldDeviationStreak>=3){long now=SystemClock.elapsedRealtime();if(now-lastActivityAlert>=30000){lastActivityAlert=now;String detail=String.format(Locale.US,"Potential sensor activity detected: magnetic-field magnitude shifted %.1f µT from this session baseline. Check phone movement, nearby metal, chargers and electronics. This is an environmental change, not evidence of paranormal activity.",magnitude-fieldBaselineMean);activityWarning.setText("⚠  "+detail);activityWarning.setVisibility(View.VISIBLE);activityWarning.setTextColor(AMBER);logEvent("ENVIRONMENTAL_CHANGE_WARNING",detail);Toast.makeText(this,detail,Toast.LENGTH_LONG).show();}}}}
    private void refreshReadings(){if(sensorCards==null)return;sensorCards.removeAllViews();readingCard("MAGNETIC FIELD",String.format(Locale.US,"X  %+.2f     Y  %+.2f     Z  %+.2f µT",mx,my,mz),"Nearby metal and powered electronics can affect readings.");readingCard("MOTION CONTEXT",String.format(Locale.US,"Accel  %+.2f  %+.2f  %+.2f m/s²",ax,ay,az),"Movement context · not an anomaly indicator.");readingCard("ROTATION",String.format(Locale.US,"Gyro  %+.2f  %+.2f  %+.2f rad/s",gx,gy,gz),"Device orientation and handling context.");readingCard("AMBIENT SENSORS",(Float.isNaN(lux)?"Light unavailable":String.format(Locale.US,"Light %.1f lx",lux))+"     ·     "+(Float.isNaN(pressure)?"Pressure unavailable":String.format(Locale.US,"%.1f hPa",pressure)),"Phone temperature is not a room-temperature reading.");sampleLabel.setText(String.valueOf(sampleCount));}
    private void readingCard(String heading,String val,String note){LinearLayout c=card();c.setOrientation(1);sensorCards.addView(c,lp(-1,-2,0,0,0,8));LinearLayout r=new LinearLayout(this);c.addView(r);TextView h=label(heading,10,SUB);h.setLetterSpacing(.08f);r.addView(h,new LinearLayout.LayoutParams(0,-2,1));View dot=new View(this);dot.setBackground(round(MINT,99));r.addView(dot,lp(6,6,0,2,0,0));TextView v=label(val,15,TEXT);v.setTypeface(null,1);c.addView(v,lp(-1,-2,0,8,0,3));c.addView(label(note,11,SUB));}
    private void addObservation(){EditText input=new EditText(this);input.setHint("What did you observe? Include context or possible explanations.");input.setTextColor(TEXT);input.setHintTextColor(SUB);new AlertDialog.Builder(this).setTitle("Timestamped observation").setView(input).setNegativeButton("CANCEL",null).setPositiveButton("ADD",(d,w)->{String note=input.getText().toString().trim();if(note.isEmpty())return;String ts=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ",Locale.US).format(new Date());String entry=SystemClock.elapsedRealtimeNanos()+",\""+ts+"\",,,,,,OBSERVATION,\""+note.replace("\"","\"\"")+"\"";rows.add(entry);if(!recording&& !sessionId.isEmpty())saveSession();Toast.makeText(this,"Observation timestamped",Toast.LENGTH_SHORT).show();}).show();}
    private void openLibrary(){File dir=new File(getFilesDir(),"sessions");File[] files=dir.listFiles((d,n)->n.endsWith(".csv"));if(files==null||files.length==0){new AlertDialog.Builder(this).setTitle("Saved sessions").setMessage("No completed sessions on this device yet.").setPositiveButton("OK",null).show();return;}String[] names=new String[files.length];for(int i=0;i<files.length;i++)names[i]=files[i].getName().replace("session-","").replace(".csv","");new AlertDialog.Builder(this).setTitle("Saved sessions · this device").setItems(names,(dialog,which)->{try{rows.clear();try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(files[which]),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null)rows.add(line);}sessionId=names[which];mediaUris.clear();audioFiles.clear();android.content.SharedPreferences saved=getSharedPreferences("sessions",0);String ms=saved.getString("media_"+sessionId,"");if(!ms.isEmpty())for(String u:ms.split("\\|"))try{mediaUris.add(Uri.parse(u));}catch(Exception ignored){}String as=saved.getString("audio_"+sessionId,"");if(!as.isEmpty())for(String path:as.split("\\|")){File a=new File(path);if(a.exists())audioFiles.add(a);}caseName=saved.getString("case_"+sessionId,caseName);site=saved.getString("site_"+sessionId,site);team=saved.getString("team_"+sessionId,team);statusLabel.setText("Loaded saved session · "+rows.size()+" records");Toast.makeText(this,"Session loaded for export",Toast.LENGTH_SHORT).show();}catch(IOException e){Toast.makeText(this,"Could not open session",Toast.LENGTH_LONG).show();}}).setNegativeButton("CANCEL",null).show();}
    private void export(){if(rows.size()<=1){Toast.makeText(this,"Start a session and capture readings first.",Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"ghost-hunter-"+(sessionId.isEmpty()?"session":sessionId)+".csv");startActivityForResult(i,42);}
    @Override protected void onActivityResult(int req,int result,Intent data){
        super.onActivityResult(req,result,data);
        if(req==44||req==45){
            if(result==RESULT_OK&&pendingMedia!=null){mediaUris.add(pendingMedia);logEvent(req==44?"PHOTO_CAPTURE":"VIDEO_CAPTURE",pendingMedia.toString());saveSession();Toast.makeText(this,"Original media saved; metadata linked to session",Toast.LENGTH_SHORT).show();}
            else if(pendingMedia!=null)getContentResolver().delete(pendingMedia,null,null);
            pendingMedia=null;return;
        }
        if((req==42||req==50||req==51)&&result==RESULT_OK&&data!=null){
            Uri destination=data.getData();
            try(OutputStream out=getContentResolver().openOutputStream(destination)){
                if(req==42){for(String row:rows)out.write((row+"\n").getBytes(StandardCharsets.UTF_8));}
                else if(pendingExport!=null)try(InputStream in=new FileInputStream(pendingExport)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
            }catch(Exception e){Toast.makeText(this,"Export failed: "+e.getMessage(),Toast.LENGTH_LONG).show();return;}
            if(req==51){Intent share=new Intent(Intent.ACTION_SEND);share.setType("application/zip");share.putExtra(Intent.EXTRA_STREAM,destination);share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Share case bundle with your team"));}
            Toast.makeText(this,"Export complete",Toast.LENGTH_SHORT).show();
        }
    }
    private void updateClock(){long seconds=(SystemClock.elapsedRealtime()-started)/1000;timeLabel.setText(String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60));}
    private void metric(LinearLayout parent,String name,String initial){LinearLayout col=new LinearLayout(this);col.setOrientation(1);parent.addView(col,new LinearLayout.LayoutParams(0,-2,1));col.addView(label(name,9,SUB));TextView val=label(initial,13,TEXT);val.setTypeface(null,1);col.addView(val);if(name.equals("SAMPLES"))sampleLabel=val;if(name.equals("SENSORS"))val.setText(String.valueOf(available.size()));}
    private LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setPadding(d(16),d(14),d(16),d(14));l.setBackground(round(CARD,16));return l;}
